#include "src/intern/dwgreader18.h"
#include "src/intern/dwgheadersection.h"
#include <fstream>
#include <iostream>
#include <memory>

class HeaderProbe final : public dwgReader18 {
public:
    HeaderProbe(std::unique_ptr<dwgBuffer> buffer, dwgRW* facade)
        : dwgReader18(std::move(buffer), facade) {}
    bool inspect(const char* output) {
        if (!readMetaData() || !readFileHeader()) return false;
        const auto found = sections.find(secEnum::HEADER);
        if (found == sections.end() || !parseDataPage(found->second)) return false;
        const auto& section = found->second;
        dwgBuffer buffer(objData.get(), section.size, &decoder);
        if (!buffer.setPosition(16u)) return false;
        const auto envelope = inspectDwgHeaderEnvelope(buffer, version,
                                                       appMaintenanceVersion);
        const auto count = buffer.getRawLong32();
        const auto high = dwgHeaderHasHighSizeWord(version, appMaintenanceVersion)
            ? buffer.getRawLong32() : 0u;
        const auto bits = version > DRW::AC1018 ? buffer.getRawLong32() : 0u;
        std::ofstream dump(output, std::ios::binary);
        dump.write(reinterpret_cast<const char*>(objData.get()),
                   static_cast<std::streamsize>(section.size));
        std::cout << "{\"version\":" << static_cast<unsigned>(version)
                  << ",\"maintenance\":" << static_cast<unsigned>(maintenanceVersion)
                  << ",\"appMaintenance\":" << static_cast<unsigned>(appMaintenanceVersion)
                  << ",\"logicalSize\":" << section.size
                  << ",\"allocationSize\":" << uncompSize
                  << ",\"declaredLow\":" << count << ",\"highWord\":" << high
                  << ",\"bitSize\":" << bits
                  << ",\"envelopeError\":" << static_cast<unsigned>(envelope.error)
                  << ",\"payloadEnd\":" << envelope.payloadEnd
                  << ",\"trailerEnd\":" << envelope.trailerEnd << "}\n";
        return buffer.isGood() && dump.good();
    }
};

int main(int argc, char** argv) {
    if (argc != 3) return 2;
    dwgRW facade(argv[1]);
    (void)facade.getPreview(); // Detect version using the existing file facade.
    if (facade.getVersion() != DRW::AC1027
        && facade.getVersion() != DRW::AC1032) return 3;
    std::ifstream source(argv[1], std::ios::binary);
    HeaderProbe probe(std::make_unique<dwgBuffer>(&source), &facade);
    return probe.inspect(argv[2]) ? 0 : 4;
}
